<script setup lang="ts">
import { ref } from 'vue'
import { app } from '../session'
import { mine, choose, forget, exportHero } from '../heroes'
import { sheet, type Hero } from '../rules/hero'
import Portrait from './Portrait.vue'
import Creator from './Creator.vue'
import HeroSheet from './HeroSheet.vue'
import Bring from './Bring.vue'
import Bar from './Bar.vue'
const what = ref<'' | 'make' | 'bring'>(''), edit = ref<Hero | null>(null), del = ref(''), view = ref(''); const from = app.modalArg as string
const back = () => { app.screen = app.inviteHash || from === 'join' ? 'join' : from === 'shelf' ? 'shelf' : from === 'new' ? 'new' : 'title' }
const made = (id: string) => { const was = edit.value; what.value = ''; edit.value = null; if (id) { choose(id); if (!was && (app.inviteHash || ['join', 'new', 'shelf'].includes(from))) back() } }
</script>
<template><Creator v-if="what === 'make'" @done="made" /><Bring v-else-if="what === 'bring'" :edit="edit" @done="made" /><main v-else class="pg paper"><Bar title="Heroes" @back="back" /><div class="bd scroll">
  <div class="two"><button @click="what = 'make'"><b>Make a hero</b><small>Twelve classes, twelve races. Six pages, and a figure you can turn in your hand.</small></button><button @click="edit = null; what = 'bring'"><b>Bring your own sheet</b><small>From paper, PDF, D&amp;D Beyond, Foundry or plain text. Your numbers, your attacks, your features.</small></button></div>
  <p v-if="!mine.list.length" class="none">No one here yet. Heroes are kept in this browser and keep what they win.</p>
  <div class="list"><article v-for="h in mine.list" :key="h.id" :class="{ on: mine.chosen === h.id, dead: h.dead }"><button class="face" :aria-label="'Choose ' + h.name" @click="choose(h.id)"><Portrait :hero="h" :size="150" frame="bust" /></button><div class="i"><h3>{{ h.name }}</h3><p>{{ h.over?.race ?? sheet(h).race.name }} {{ h.over?.cls ?? sheet(h).cls.name.toLowerCase() + ' ' + h.level }}<template v-if="h.dead">, fallen</template></p><p class="m">{{ sheet(h).max }} hit points, AC {{ sheet(h).ac }}, {{ h.gold }} gold{{ h.over ? '. Own sheet' : '' }}</p><div class="ac"><button v-if="mine.chosen !== h.id && !h.dead" @click="choose(h.id)">Choose</button><b v-else-if="!h.dead">Chosen</b><button @click="view = h.id">Sheet</button><button @click="edit = h; what = 'bring'">Amend</button><button @click="exportHero(h)">Save to a file</button><button @click="del = h.id">Retire</button></div></div></article></div></div></main>
  <HeroSheet v-if="view" :own="mine.list.find(h => h.id === view)" @close="view = ''" />
  <div v-if="del" class="veil" @click.self="del = ''"><section class="modal paper" style="width:420px"><div class="body"><h2>Retire {{ mine.list.find(h => h.id === del)?.name }}?</h2><p style="margin-top:8px">The hero is removed from this device. Save to a file first if you may want them back.</p></div><footer><button class="btn quiet" @click="del = ''">Keep</button><button class="btn primary" @click="forget(del); del = ''">Retire</button></footer></section></div></template>
<style scoped>.pg{position:fixed;inset:0;display:flex;flex-direction:column}.bd{flex:1;min-height:0}.two{display:grid;grid-template-columns:1fr 1fr;border-bottom:2px solid var(--ink)}.two button{padding:20px clamp(18px,3.2vw,48px) 22px}.two button+button{border-left:2px solid var(--ink)}.two b{font:800 34px/1 var(--serif);display:block}.two small{font-size:17px;color:var(--ink2);display:block;margin-top:6px;max-width:46ch}.two button:hover{background:var(--spot);color:var(--on-spot)}.two button:hover small{color:inherit}.none{padding:34px clamp(18px,3.2vw,48px)}.list{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,430px),1fr));gap:26px;padding:28px clamp(18px,3.2vw,48px) 60px;max-width:1500px}article{display:flex;gap:18px;align-items:flex-start}.face{flex:none}.on .face{outline:5px solid var(--ink);outline-offset:-5px}.dead{opacity:.5}.i{min-width:0;border-top:3px solid var(--ink);flex:1;padding-top:8px;min-height:150px}h3{font:800 30px/1 var(--serif)}.i p{margin:5px 0 0;font-size:17px}.i .m{color:var(--ink2);font-size:16px}.ac{display:flex;flex-wrap:wrap;gap:2px 16px;margin-top:12px}.ac button{text-decoration:underline;text-underline-offset:4px;min-height:30px}.ac button:hover{background:var(--spot);color:var(--on-spot)}.ac b{background:var(--ink);color:var(--paper);padding:0 9px;font-weight:500;line-height:28px}@media(max-width:700px){.two{grid-template-columns:1fr}.two button+button{border-left:0;border-top:2px solid var(--ink)}.face :deep(.pt){width:104px!important;height:104px!important}}</style>
